def document(title,description,content,extra=''):
 return f'''<!doctype html><html lang="es" id="top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · El Santuario</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="theme-color" content="#f6f3ec"><meta name="robots" content="noindex,nofollow"><link rel="icon" href="/assets/editorial/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/fonts.css"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script>{extra}</head><body>{header()}{content}{footer()}</body></html>'''
def card(a,i):
 return f'''<article class="story story-{i}" data-category="{a['category']}" {'hidden' if i>3 else ''}><a class="story-image" href="/lecturas/{a['slug']}/"><img src="/assets/editorial/{a['image']}.webp" alt="{ {'coast':'Olas suaves en una cala al amanecer','ritual':'Un libro abierto y una taza de cerámica bajo la luz de la mañana','ceramic':'Piezas de cerámica artesanal y una rama en flor','garden':'Flores blancas entre hojas tropicales'}[a['image']] }" loading="lazy" width="900" height="1100"><span class="image-link" aria-hidden="true">↗</span></a><div class="story-info"><p class="eyebrow">{a['category']} <span>· {a['minutes']} MIN DE LECTURA</span></p><h3><a href="/lecturas/{a['slug']}/">{a['title']}</a></h3><p class="excerpt">{a['intro']}</p><a class="text-link" href="/lecturas/{a['slug']}/">Leer la historia {arrow}</a></div></article>'''
content=f'''<main id="main"><section class="masthead" aria-labelledby="journal-title"><div class="masthead-meta"><span>UN DIARIO DE LA CASA QUE CANTA</span><span>ZIHUATANEJO, MÉXICO</span></div><h1 id="journal-title"><i>El</i> Santuario<span class="masthead-star" aria-hidden="true">✳</span></h1><div class="masthead-base"><span>HISTORIAS PARA HABITAR LA CALMA</span><span>EDICIÓN 01 — OCTUBRE 2026</span></div></section><section class="cover"><div class="cover-copy"><p class="eyebrow"><span class="tiny-line"></span> LA HISTORIA DE PORTADA</p><h2>El arte de <br><em>no tener</em><br> prisa.</h2><p class="cover-intro">A veces, lo único que necesitamos es un horizonte. Y el tiempo suficiente para mirarlo.</p><a class="circle-link" href="/lecturas/el-arte-de-no-tener-prisa/"><span>Adentrarse en la historia</span><span class="circle-arrow" aria-hidden="true">↗</span></a><p class="cover-bottom">NATURALEZA <span>4 MIN DE LECTURA</span></p></div><a class="cover-photo" href="/lecturas/el-arte-de-no-tener-prisa/" aria-label="Leer El arte de no tener prisa"><img src="/assets/editorial/coast.webp" alt="Mar tranquilo de color jade y una orilla dorada al amanecer" fetchpriority="high" width="1536" height="1024"><span class="photo-number">01 / UNA INVITACIÓN A DETENERSE</span><span class="photo-word">Respira.</span></a></section><section class="editor-note"><span class="note-star" aria-hidden="true">✳</span><p>Pequeñas historias. Grandes pausas.<br>Un lugar para descubrir todo aquello<br>que nos hace <em>sentir en paz.</em></p><span class="note-signature">Bienvenido a nuestro mundo.</span></section><section id="diario" class="journal-section"><div class="section-heading"><div><p class="eyebrow">EL DIARIO</p><h2>El lado sereno <em>de la vida.</em></h2></div><p>Lecturas para disfrutar sin prisa.</p></div><div class="filters" role="group" aria-label="Filtrar historias por tema">{''.join(f'<button data-filter="{x}" aria-pressed="{str(i==0).lower()}" class="filter {"active" if i==0 else ""}">{x}{" <span>06</span>" if i==0 else ""}</button>' for i,x in enumerate(['Todas las historias','Naturaleza','Rituales','Arte y oficio','Sabores','Vida en la casa']))}</div><p class="sr-only" id="filter-status" aria-live="polite"></p><div class="stories">{''.join(card(a,i) for i,a in enumerate(articles[1:]+articles[:1],1))}</div><div class="more-row"><span>UN MOMENTO PARA TI</span><button id="more-stories" class="outline-button">Más historias <span aria-hidden="true">↓</span></button><span>PARA LEER Y VOLVER A LEER</span></div></section><section id="mirada" class="manifesto"><div class="manifesto-photo"><img src="/assets/editorial/garden.webp" alt="Flores de frangipani iluminadas entre hojas verdes" loading="lazy" width="1024" height="1280"><span>LA BELLEZA ESTÁ EN LOS DETALLES.</span></div><div class="manifesto-copy"><p class="eyebrow">NUESTRA MIRADA</p><h2>Un santuario<br>no es solo<br><em>un lugar.</em></h2><p>Es una luz que se queda contigo. Una conversación que se alarga. El sonido del mar cuando ya no hay nada que decir.</p><p>Este diario reúne lo que inspira nuestra forma de entender la hospitalidad: naturaleza, belleza y el placer de estar presente.</p><a class="text-link" href="/lecturas/un-lugar-para-volver-a-uno-mismo/">Conoce el espíritu de El Santuario {arrow}</a></div></section><section class="closing"><p class="eyebrow">LLEVA CONTIGO ESTA SENSACIÓN</p><h2>Hay historias que se leen.<br><em>Y otras que se viven.</em></h2><a class="outline-button" href="https://www.lacasaquecanta.com/" target="_blank" rel="noopener">Descubrir La Casa Que Canta {arrow}</a></section></main>'''
(OUT/'index.html').write_text(document('Historias para habitar la calma','El Santuario, el diario de La Casa Que Canta. Historias sobre naturaleza, arte, sabores y pequeños rituales para disfrutar sin prisa.',content),encoding='utf-8')
for a in articles:
 paragraphs=''.join(f'<section><h2>{title}</h2><p>{p}</p></section>' for title,p in a['body'])
 related=[b for b in articles if b['slug']!=a['slug']][:2]
 body=f'''<main id="main" class="article-main"><div class="article-breadcrumb"><a href="/">El Santuario</a><span>/</span><span>{a['category']}</span></div><header class="article-header"><p class="eyebrow">{a['category']} <span>· {a['minutes']} MIN DE LECTURA</span></p><h1>{a['title']}</h1><p class="article-intro">{a['intro']}</p><div class="article-meta"><span>EL SANTUARIO · {a['date']}</span><button class="save-story" data-slug="{a['slug']}" aria-pressed="false"><span aria-hidden="true">♡</span> Guardar lectura</button></div></header><figure class="article-hero"><img src="/assets/editorial/{a['image']}.webp" alt="Imagen de concepto para {html.escape(a['title'])}" width="1536" height="1024"><figcaption>UNA MIRADA AL ARTE DE VIVIR SIN PRISA · IMAGEN DE CONCEPTO</figcaption></figure><div class="article-layout"><aside><p class="eyebrow">EL SANTUARIO</p><p>Historias para<br>habitar la calma.</p><a href="/#diario">← Volver al diario</a></aside><div class="article-body">{paragraphs}<blockquote>“{a['quote']}”</blockquote><div class="article-end"><span>UN DIARIO DE LA CASA QUE CANTA</span><a href="/#diario">Seguir leyendo ↗</a></div></div></div><section class="related"><p class="eyebrow">EL VIAJE CONTINÚA</p><h2>Quédate <em>un poco más.</em></h2><div class="related-grid">{''.join(card(b,i) for i,b in enumerate(related,1))}</div></section></main>'''
 path=OUT/'lecturas'/a['slug'];path.mkdir(parents=True,exist_ok=True);(path/'index.html').write_text(document(a['title'],a['intro'],body),encoding='utf-8')
